class Solution:
    def runWidths(self, values: list[int]) -> list[int]:
        widths = []
        for index, value in enumerate(values):
            if index == 0 or value != values[index - 1]:
                widths.append(1)
            else:
                widths[-1] += 1
        return widths

class Solution  {
    public int[] runWidths(int[] values)  {
        ArrayList<Integer> a=new ArrayList<>();
        for(int i=0;i<values.length;i++)  {
            if(i==0||values[i]!=values[i-1])a.add(1);
            else a.set(a.size()-1,a.get(a.size()-1)+1);
        }
        return a.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution  {
    runWidths(values:number[]):number[] {
        const a:number[]=[];
        values.forEach((v,i)=> {
            if(i===0||v!==values[i-1])a.push(1);else a[a.length-1]++;
        }
        );
        return a;
    }
}
